/**
 * Every user-facing string of the history feature lives here. The timeline (the History tab) reads the i18n
 * catalogue; the change list and the diff sheet are still English and move the same way next.
 * Plain words, no em dashes, no exclamation marks. The change lines themselves ("Renamed the Home screen to
 * Today") are generated by src/core/history and are English for now.
 */
import type { VersionEvent, VersionOrigin } from '@/core/history';
import { t as gt } from '@/i18n/active';

export const copy = {
  changeList: {
    get title() { return gt('history.changeList.title'); },
    get empty() { return gt('history.changeList.empty'); },
    count: (n: number): string => gt('history.changeList.count', { count: n }),
    get onlyLook() { return gt('history.changeList.onlyLook'); },
    get entriesNote() { return gt('history.changeList.entriesNote'); },
    get affectsEntries() { return gt('history.changeList.affectsEntries'); },
    get before() { return gt('history.changeList.before'); },
    get after() { return gt('history.changeList.after'); },
  },
  // The History tab speaks the UI language (keys history.timeline.*). Getters, so a language switch shows on the next render.
  timeline: {
    get title() { return gt('history.timeline.title'); },
    get loading() { return gt('history.timeline.loading'); },
    get empty() { return gt('history.timeline.empty'); },
    get current() { return gt('history.timeline.current'); },
    events: {
      get created() { return gt('history.timeline.event.created'); },
      get edited() { return gt('history.timeline.event.edited'); },
      get restored() { return gt('history.timeline.event.restored'); },
      get imported() { return gt('history.timeline.event.imported'); },
    } satisfies Record<VersionEvent, string>,
    origins: {
      get user() { return gt('history.timeline.origin.user'); },
      get ai() { return gt('history.timeline.origin.ai'); },
      get import() { return gt('history.timeline.origin.import'); },
      get marketplace() { return gt('history.timeline.origin.marketplace'); },
    } satisfies Record<VersionOrigin, string>,
    get today() { return gt('common.today'); },
    get yesterday() { return gt('history.timeline.yesterday'); },
    get filterLabel() { return gt('history.timeline.filterLabel'); },
    get filterAll() { return gt('history.timeline.filterAll'); },
    get noMatches() { return gt('history.timeline.noMatches'); },
    get blocked() { return gt('history.timeline.blocked'); },
    get seeChanges() { return gt('history.timeline.seeChanges'); },
    seeChangesHint: (n: number): string => gt('history.timeline.seeChangesHint', { version: n }),
    get preview() { return gt('history.timeline.preview'); },
    get showing() { return gt('history.timeline.showing'); },
    previewHint: (n: number): string => gt('history.timeline.previewHint', { version: n }),
    get restore() { return gt('history.timeline.restore'); },
    restoreHint: (n: number): string => gt('history.timeline.restoreHint', { version: n }),
    get dataTouched() { return gt('history.timeline.dataTouched'); },
  },
  diff: {
    title: (n: number): string => gt('history.diff.title', { n }),
    get changedHere() { return gt('history.diff.changedHere'); },
    get ifRestored() { return gt('history.diff.ifRestored'); },
    get earliest() { return gt('history.diff.earliest'); },
    get same() { return gt('history.diff.same'); },
    get unavailable() { return gt('history.diff.unavailable'); },
    get restoreNote() { return gt('history.diff.restoreNote'); },
    get dataNote() { return gt('history.diff.dataNote'); },
    get restoreButton() { return gt('history.diff.restoreButton'); },
    restoreButtonHint: (n: number): string => gt('history.diff.restoreButtonHint', { n }),
    get close() { return gt('history.diff.close'); },
    get currentNote() { return gt('history.diff.currentNote'); },
  },
} as const;
